import sys

def line(a):
    take, skip = 0, 0
    for v in a:
        take, skip = skip + v, max(take, skip)
    return max(take, skip)

def main():
    data = sys.stdin.read().split()
    n, c = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    if c == 0 or n == 1:
        print(line(a))
    else:
        print(max(line(a[1:]), line(a[:-1])))

main()

