import sys

def best(a):
    dp = []
    for i, v in enumerate(a):
        dp.append(v + max([0] + dp[:max(0, i - 1)]))
    return max([0] + dp)

data = sys.stdin.read().split()
n, c = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]
if c == 0:
    print(best(a))
elif n == 1:
    print(a[0])
else:
    # either house 0 is robbed (so houses 1 and n-1 are off limits) or it is not
    print(max(a[0] + best(a[2:n - 1]), best(a[1:])))

